 1→//! Template caching system.
 2→//!
 3→//! This module provides disk-based caching for remote templates with
 4→//! TTL-based and content-based (ETag/git) invalidation strategies.
 5→
 6→pub mod entry;
 7→pub mod revalidation;
 8→pub mod store;
 9→pub mod validation;
10→
11→pub use entry::{CacheEntry, CacheMetadata};
12→pub use revalidation::{needs_revalidation, CacheRevalidator, RevalidationResult};
13→pub use store::CacheStore;
14→pub use validation::{format_duration, parse_ttl, CacheValidator, ValidationResult};
15→
16→/// Get the default cache directory.
17→pub fn default_cache_dir() -> std::path::PathBuf {
18→    dirs::cache_dir()
19→        .unwrap_or_else(|| std::path::PathBuf::from("."))
20→        .join("bivvy")
21→        .join("templates")
22→}
23→
24→#[cfg(test)]
25→mod tests {
26→    use super::*;
27→
28→    #[test]
29→    fn default_cache_dir_valid() {
30→        let path = default_cache_dir();
31→        assert!(path.ends_with("templates"));
32→    }
33→}
