  1→//! Install method detection.
  2→//!
  3→//! Detects how bivvy was installed to determine the update mechanism.
  4→
  5→use std::env;
  6→use std::path::{Path, PathBuf};
  7→use std::process::Command;
  8→
  9→/// How bivvy was installed.
 10→#[derive(Debug, Clone, PartialEq, Eq)]
 11→pub enum InstallMethod {
 12→    /// Installed via cargo install
 13→    Cargo,
 14→    /// Installed via Homebrew
 15→    Homebrew,
 16→    /// Downloaded binary or built from source
 17→    Manual { path: PathBuf },
 18→    /// Could not determine install method
 19→    Unknown,
 20→}
 21→
 22→impl InstallMethod {
 23→    /// Get the update command for this install method.
 24→    pub fn update_command(&self) -> Option<String> {
 25→        match self {
 26→            InstallMethod::Cargo => Some("cargo install bivvy --force".to_string()),
 27→            InstallMethod::Homebrew => Some("brew upgrade bivvy".to_string()),
 28→            InstallMethod::Manual { .. } => None,
 29→            InstallMethod::Unknown => None,
 30→        }
 31→    }
 32→
 33→    /// Check if this method supports automatic updates.
 34→    pub fn supports_auto_update(&self) -> bool {
 35→        matches!(self, InstallMethod::Cargo | InstallMethod::Homebrew)
 36→    }
 37→
 38→    /// Get a human-readable name for this install method.
 39→    pub fn name(&self) -> &str {
 40→        match self {
 41→            InstallMethod::Cargo => "cargo",
 42→            InstallMethod::Homebrew => "homebrew",
 43→            InstallMethod::Manual { .. } => "manual",
 44→            InstallMethod::Unknown => "unknown",
 45→        }
 46→    }
 47→}
 48→
 49→/// Detect how bivvy was installed.
 50→pub fn detect_install_method() -> InstallMethod {
 51→    // Get the current executable path
 52→    let exe_path = match env::current_exe() {
 53→        Ok(path) => path,
 54→        Err(_) => return InstallMethod::Unknown,
 55→    };
 56→
 57→    // Check if it's in cargo bin directory
 58→    if is_cargo_install(&exe_path) {
 59→        return InstallMethod::Cargo;
 60→    }
 61→
 62→    // Check if it's managed by Homebrew
 63→    if is_homebrew_install(&exe_path) {
 64→        return InstallMethod::Homebrew;
 65→    }
 66→
 67→    // Manual install (downloaded binary or built from source)
 68→    InstallMethod::Manual { path: exe_path }
 69→}
 70→
 71→fn is_cargo_install(exe_path: &Path) -> bool {
 72→    // Check if executable is in ~/.cargo/bin/
 73→    if let Some(home) = dirs::home_dir() {
 74→        let cargo_bin = home.join(".cargo").join("bin");
 75→        if exe_path.starts_with(&cargo_bin) {
 76→            return true;
 77→        }
 78→    }
 79→
 80→    // Check CARGO_HOME environment variable
 81→    if let Ok(cargo_home) = env::var("CARGO_HOME") {
 82→        let cargo_bin = PathBuf::from(cargo_home).join("bin");
 83→        if exe_path.starts_with(&cargo_bin) {
 84→            return true;
 85→        }
 86→    }
 87→
 88→    false
 89→}
 90→
 91→fn is_homebrew_install(exe_path: &Path) -> bool {
 92→    // Check common Homebrew paths
 93→    let homebrew_paths = [
 94→        "/usr/local/Cellar/",          // Intel macOS
 95→        "/opt/homebrew/Cellar/",       // ARM macOS
 96→        "/home/linuxbrew/.linuxbrew/", // Linux
 97→    ];
 98→
 99→    let exe_str = exe_path.to_string_lossy();
100→    for prefix in &homebrew_paths {
101→        if exe_str.starts_with(prefix) {
102→            return true;
103→        }
104→    }
105→
106→    // Also check if it's a symlink from Homebrew bin
107→    let homebrew_bins = ["/usr/local/bin/bivvy", "/opt/homebrew/bin/bivvy"];
108→
109→    for bin in &homebrew_bins {
110→        if exe_path.to_string_lossy() == *bin {
111→            // Check if it's actually a Homebrew-managed binary
112→            if let Ok(output) = Command::new("brew")
113→                .args(["list", "--formula", "bivvy"])
114→                .output()
115→            {
116→                if output.status.success() {
117→                    return true;
118→                }
119→            }
120→        }
121→    }
122→
123→    false
124→}
125→
126→/// Get the path where bivvy is installed.
127→pub fn get_install_path() -> Option<PathBuf> {
128→    env::current_exe().ok()
129→}
