189→                .path("/template.yml")
190→                .header("If-None-Match", "\"etag-v1\"");
191→            then.status(304);
192→        });
193→
194→        let temp = TempDir::new().unwrap();
195→        let store = CacheStore::new(temp.path());
196→        let git_dir = temp.path().join("git");
197→        let revalidator = CacheRevalidator::new(&store, git_dir);
198→
199→        // Create an expired cache entry with an etag
200→        let mut entry = store
201→            .store("http:test", "template", "old content", 0)
202→            .unwrap();
203→        entry.metadata.etag = Some("\"etag-v1\"".to_string());
204→        store.update(&entry).unwrap();
205→
206→        let result = revalidator
207→            .revalidate_etag(&server.url("/template.yml"), &mut entry, 3600)
208→            .unwrap();
209→
210→        mock.assert();
211→        assert!(matches!(result, RevalidationResult::Unchanged));
212→        // TTL should be extended
213→        assert!(!entry.is_expired());
214→    }
215→
216→    #[test]
217→    fn etag_revalidation_updated_on_200() {
218→        let server = MockServer::start();
219→
220→        server.mock(|when, then| {
221→            when.method(GET).path("/template.yml");
222→            then.status(200)
223→                .header("ETag", "\"etag-v2\"")
224→                .body("new content");
225→        });
226→
227→        let temp = TempDir::new().unwrap();
228→        let store = CacheStore::new(temp.path());
229→        let git_dir = temp.path().join("git");
230→        let revalidator = CacheRevalidator::new(&store, git_dir);
231→
232→        // Create an expired cache entry with an old etag
233→        let mut entry = store
234→            .store("http:test", "template", "old content", 0)
235→            .unwrap();
236→        entry.metadata.etag = Some("\"etag-v1\"".to_string());
237→        store.update(&entry).unwrap();
238→
239→        let result = revalidator
240→            .revalidate_etag(&server.url("/template.yml"), &mut entry, 3600)
241→            .unwrap();
242→
