    }

    #[test]
    fn different_entries_have_different_paths() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template1");
        let path2 = store.content_path("http:test", "template2");

        assert_ne!(path1, path2);
    }

    #[test]
    fn concurrent_stores_maintain_size_consistency() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();
        let num_threads = 8;
        let iterations = 50;

        for _ in 0..iterations {
            let barrier = Arc::new(Barrier::new(num_threads));
            let handles: Vec<_> = (0..num_threads)
                .map(|i| {
                    let root = root.clone();
                    let barrier = barrier.clone();
                    thread::spawn(move || {
                        let store = CacheStore::new(&root);
                        barrier.wait();
                        let content = "x".repeat((i + 1) * 1000);
                        store.store("http:race", "tpl", &content, 3600).unwrap();
                    })
                })
                .collect();

            for h in handles {
                h.join().unwrap();
            }
        }

        let store = CacheStore::new(temp.path());
        let entry = store.load("http:race", "tpl").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();
        assert_eq!(
            entry.metadata.size_bytes,
            content.len() as u64,
            "Metadata size {} doesn't match content size {}",
            entry.metadata.size_bytes,
            content.len()
        );
    }

    #[test]
    fn concurrent_loads_never_see_corrupt_metadata() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = temp.path().to_path_buf();
        let num_threads = 8;
        let barrier = Arc::new(Barrier::new(num_threads));

        let handles: Vec<_> = (0..num_threads)
            .map(|i| {
                let root = root.clone();
                let barrier = barrier.clone();
                thread::spawn(move || {
                    let store = CacheStore::new(&root);
                    barrier.wait();

                    for iter in 0..100 {
                        let content = format!("thread-{}-iter-{}", i, iter);
                        store.store("http:race2", "tpl", &content, 3600).unwrap();

                        // Concurrent reads should never return corrupt metadata
                        if let Ok(Some(entry)) = store.load("http:race2", "tpl") {
                            assert!(
                                store.read_content(&entry).is_ok(),
                                "Failed to read content for valid metadata"
                            );
                        }
                    }
                })
            })
            .collect();

        for h in handles {
            h.join().unwrap();
        }
    }
}

